#include "stdlib/math/base/special/log10f.h"
#include "stdlib/number/float32/base/to_word.h"
#include "stdlib/number/float32/base/from_word.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/kernel_log1pf.h"
#include "stdlib/constants/float32/pinf.h"
#include "stdlib/constants/float32/ninf.h"
#include <stdint.h>

static const float TWO25 = 3.3554432000e+07f;     // 0x4c000000
static const float IVLN10 = 4.3429449201e-01f;    // 0x3ede5bd9
static const float LOG10_2HI = 3.0102999566e-01f; // 0x3e9a209a
static const float LOG10_2LO = 3.6942390772e-13f; // 0x2d022b36

// 0x7f800000 = 2139095040
static const int32_t FLT_MAX_EXP_BIT_MASK = 0x7f800000;

// 0x00800000 = 8388608
static const int32_t FLT_MIN_NORMAL_EXP = 0x00800000;

// 0x3f800000 = 1065353216 => bias 127
static const int32_t FLT_BIAS_EXP = 0x3f800000;

/**
* Evaluates the common logarithm (base ten) of a single-precision floating-point number.
*
* @param x    input value
* @return     output value
*/
float stdlib_base_log10f( const float x ) {
	float hfsq;
	float hi;
	float lo;
	float r;
	float f;
	float y;
	int32_t hx;
	int32_t i;
	int32_t k;

	if ( stdlib_base_is_nanf( x ) || x < 0.0f ) {
		return 0.0f / 0.0f; // NaN
	}
	stdlib_base_float32_to_word( x, (uint32_t *)&hx );
	k = 0;
	if ( hx < FLT_MIN_NORMAL_EXP ) {
		// x < 2**-126
		if ( ( hx & 0x7fffffff ) == 0 ) {
			return STDLIB_CONSTANT_FLOAT32_NINF; // log(+-0) = -inf
		}
		k -= 25;
		x *= TWO25; // subnormal number, scale up x
		stdlib_base_float32_to_word( x, (uint32_t *)&hx );
	}
	if ( hx >= FLT_MAX_EXP_BIT_MASK ) {
		return x + x;
	}
	if ( hx == FLT_BIAS_EXP ) {
		return 0.0f; // log(1) = +0
	}
	k += ( hx >> 23 ) - 127;
	hx &= 0x007fffff;
	i = ( hx + 0x95f64 ) & 0x800000;
	// Normalize x or x/2...
	stdlib_base_float32_from_word( (uint32_t)( hx | ( i ^ FLT_BIAS_EXP ) ), &x );
	k += ( i >> 23 );
	y = (float)k;
	f = x - 1.0f;
	hfsq = 0.5f * f * f;
	r = stdlib_base_kernel_log1pf( f );

	hi = f - hfsq;
	stdlib_base_float32_to_word( hi, (uint32_t *)&hx );
	stdlib_base_float32_from_word( (uint32_t)( hx & 0xfffff000 ), &hi );
	lo = ( f - hi ) - hfsq + r;
	return ( y * LOG10_2LO ) + ( ( lo + hi ) * IVLN10 ) + ( y * LOG10_2HI );
}
